// 从符号和具体数值开始。示意地址不代表实际运行地址，普通 int 大小由示例前提给出。
export const beginnerLessons=[];
export const beginnerPath=['c-start-variable','c-start-bytes','c-start-expression','c-sizeof','c-address','c-pointer-declare','c-dereference','c-pointer-change','c-array-start','c-function-start','c-struct-start'];
function B(id,title,goal,sections,steps,worked,trap,quiz){
  beginnerLessons.push({module:'c',id,title,level:'入门',summary:goal,beginner:true,
    basics:{goal,sections},points:steps,
    tutorial:{question:goal,steps,worked,trap},
    quiz:quiz.map((q,i)=>({id:`${id}-q${i+1}`,prompt:q[0],options:q[1],answer:q[2],explain:q[3]}))});
}
const S=(title,paragraphs,extra={})=>({title,paragraphs,...extra});

B('c-pointer-declare','06 · 指针：保存地址的变量','读懂 int *p = &x;：p 保存 x 的地址，不是保存整数 x 的副本。',[
 S('先有变量，再保存它的位置',['前一课中 x 保存整数，而 &x 取得 x 的地址。我们可以把这个地址也保存下来，之后再根据地址找到 x。','专门保存这种地址的变量叫“指针”。这里 p 是一个指针变量，类型为 int*，意思是指向 int 的指针。'],{code:'int x = 10;\nint *p = &x;',read:[['int x = 10;','创建整数变量 x，内容为 10。'],['&x','取得 x 的地址。'],['int *p = &x;','创建指针变量 p，把 x 的地址作为 p 的初值。']]}),
 S('这一行的每部分是什么？',['在声明中，* 和变量名结合，说明 p 是指针。这里没有“先找到一个叫 p 的指针并读取它”的动作，因为正在创建 p。','int *p 与 int* p 在这个单变量声明里含义相同。空格位置不改变“p 指向 int”的意思。'],{code:'int *p = &x;',tokens:[['int','指明 p 将指向的目标是 int 类型。'],['*p（声明中）','声明 p 为指针变量；这个星号不是乘法。'],['=','用右边的地址初始化 p。'],['&x','取得 x 的地址，交给 p 保存。'],[';','结束声明。']]}),
 S('现在有两个变量，不是一个',['假设 x 的地址是 0x1000，p 自己的地址是 0x2000。x 里面是 10；p 里面是 0x1000。指针也需要自己的存储位置。','以后使用 p，取得的是它保存的地址。使用 &p，取得的是 p 自己的位置；这两个地址在本例里不同。下一课再用 *p 访问 x。'],{table:{heads:['名字/表达式','本例取得的值','解释'],rows:[['x','10','整数变量的内容。'],['&x','0x1000','x 的位置。'],['p','0x1000','指针中保存的目标地址。'],['&p','0x2000','指针变量 p 自己的位置。']]},note:'0x1000 和 0x2000 均为示意。真实程序无需手工填写它们。'})
],['指针是保存地址的变量；int* 表示它指向 int 类型的目标。','int *p=&x 中，声明部分创建 p，右边 &x 提供 x 的地址作为初值。','p 与 x 是两个变量：x 保存整数，p 保存地址，p 自己也有地址。'],{prompt:'int x=10; int *p=&x; 假设 &x 为 0x1000，&p 为 0x2000。p 的值是 10、0x1000 还是 0x2000？',answer:'p 的值为 0x1000。右边 &x 取得 x 的地址，初始化时将它存入 p。10 是 x 的内容；0x2000 是 p 自己的位置，不是 p 保存的内容。'},'int *p; 只声明而未初始化时，不能立即使用 *p。先让 p 指向有效变量，或用 NULL 表示暂时没有目标，NULL 也不能解引用。',[
 ['int x=10; int *p=&x; p 保存什么？',['x 的地址','整数 10 的副本','x 的名字字符串','sizeof(x)'],0,'右边 &x 是地址，初始化后 p 保存该地址。读取目标整数需要下一课的 *p。'],
 ['int *p=&x; 声明部分的 * 表示？',['p 是指向 int 的指针','int 与 p 相乘','创建 x 的副本','求 p 的大小'],0,'这是声明语法，用来说明 p 的类型，尚不是表达式中的目标访问。'],
 ['p 和 &p 的区别？',['p 是目标地址，&p 是 p 自己的地址','完全相同且类型也相同','&p 是乘法','p 没有存储位置'],0,'p 是变量，它的内容与它所在位置是两件事。&p 的类型比 p 多一级指针，后面的二级指针课再展开。']
]);

B('c-dereference','07 · *p：沿地址访问目标','声明之后，表达式里的 *p 表示访问 p 指向的变量，这叫解引用。',[
 S('已经有了地址，怎样找到里面的数据？',['先看两行：x 保存 10，p 保存 x 的地址。表达式 *p 可以理解为“沿着 p 里保存的地址，到那里访问一个 int”。','读取 *p 时，就读取到 x 的内容。因此这里 *p 为 10。它不是把 p 与什么东西相乘。'],{code:'int x = 10;\nint *p = &x;\nint y = *p;',read:[['int x=10;','x 里面先有 10。'],['int *p=&x;','p 指向 x。'],['int y=*p;','沿 p 找到 x，读取 10，用它创建 y。']]}),
 S('读取目标和写入目标',['*p 可以出现在右边：y=*p，读取目标内容。也可以出现在左边：*p=7，将 7 写入目标。','因为 p 此时指向 x，所以 *p=7 改的是 x。p 保存的地址没有变。这种访问操作叫“解引用”，先记住它就是按地址访问目标。'],{code:'int x = 10;\nint *p = &x;\n*p = 7;  // x 变为 7，p 仍指向 x',tokens:[['p','取出 p 保存的地址。'],['*p（表达式中）','访问该地址对应的目标变量。'],['*p = 7','把 7 写进目标，这里目标是 x。']]}),
 S('同一个 * 有三种常见用法',['你看到星号时，先判断代码是在声明，还是在计算表达式。表达式中还要看星号左右是不是都有操作数。','声明 int *p 说明变量的类型；表达式 *p 访问目标；表达式 a*b 则是乘法。三者不能一概理解为“指针”。'],{table:{heads:['写法','这里的 * 在做什么'],rows:[['int *p = &x;','声明 p 是指针。'],['y = *p;','读取 p 指向的目标。'],['*p = 7;','向 p 指向的目标写入。'],['y = 2 * 3;','两个数相乘，得到 6。']]},note:'只在 p 指向有效、类型合适的变量时才能这样访问。不能对空指针、未初始化指针或已经失效的地址使用 *p。'})
],['表达式 *p 访问指针 p 指向的目标，读取它可得到目标当前内容。','*p 在赋值左边时表示目标存储位置，因此 *p=7 能修改 p 指向的变量。','声明中的 *、表达式中的单目 * 与乘法 * 需要按上下文区分。'],{prompt:'int x=10; int *p=&x; int y=*p; *p=7; 最终 x 和 y 各是多少？',answer:'创建 y 时，*p 读取到当时的 x=10，所以 y 保存独立的整数 10。下一行 *p=7 改变 x。最终 x=7、y=10，p 仍指向 x；y 不会自动跟着 x 变化。'},'解引用不是复制指针。y=*p 复制目标的整数值，int *q=p 则复制地址值。',[
 ['int x=10; int *p=&x; *p 的值？',['10','x 的字节数','p 的名字','固定为 0'],0,'p 存 x 的地址，*p 沿这个地址读取 x，所以得到 10。'],
 ['上述声明后执行 *p=7，哪个变量的内容改变？',['x','只有 p 的地址值','没有变量','sizeof(int)'],0,'*p 在左边表示目标位置；p 指向 x，所以写的是 x，地址没有重设。'],
 ['在 y=2*3 中，* 是什么？',['乘法','指针声明','解引用 p','取地址'],0,'左右有两个数作为操作数，这里计算 2×3。它与表达式 *p 的单目访问不同。']
]);

B('c-pointer-change','08 · p= 与 *p=：改地址还是改内容','分别观察 p=&b 与 *p=9，搞清究竟是谁被修改。',[
 S('先让 p 指向 a',['设 a=10、b=20，p 先保存 a 的地址。现在 p 的目标是 a，所以 *p 为 10。','本课只涉及两个有效整数变量，不移动指针到未知位置。'],{code:'int a = 10;\nint b = 20;\nint *p = &a;'}),
 S('p=&b：换一个目标',['左边只有 p，说明要修改指针变量自己。右边 &b 是 b 的地址，因此 p 改为指向 b。','a 和 b 保存的整数都没有被这行修改。地址值改变后，再读 *p，就从 b 读取 20。'],{code:'p = &b;',table:{heads:['执行前/后','a','b','p 的目标','*p'],rows:[['执行前','10','20','a','10'],['执行后','10','20','b','20']]}}),
 S('*p=9：改当前目标',['现在 p 指向 b。左边 *p 表示 b 所在的目标位置，因此将 9 写入 b。','如果 p 没有先换目标、仍指向 a，相同 *p=9 就会改 a。所以读指针题要逐行更新它现在指向谁。'],{code:'*p = 9;',table:{heads:['执行前/后','a','b','p 的目标','*p'],rows:[['执行前','10','20','b','20'],['执行后','10','9','b','9']]}})
],['p=&b 修改 p 保存的地址，让它换目标，不修改 a 或 b 的数据。','*p=9 修改当前目标的内容，p 保存的地址本身不变。','判断 *p 改谁之前，先确定执行到这行时 p 指向谁。'],{prompt:'int a=1,b=2; int *p=&a; *p=5; p=&b; *p=8; 最终 a、b 和 p 的目标？',answer:'初始 p 指向 a，所以第一条 *p=5 使 a=5。p=&b 将目标换为 b，没有改 a 或 b 的值。最后 *p=8 使 b=8。最终 a=5、b=8，p 指向 b。'},'p=9 并不是把目标改成 9；指针赋值需要合适的地址值。想写目标整数应使用 *p=9。',[
 ['p 当前指向 a，执行 p=&b，会？',['让 p 指向 b','把 b 的值写到 a','把 a 的值写到 b','把 b 改为 0'],0,'赋值左边为 p，所以修改指针保存的地址，不复制目标整数。'],
 ['p 指向 b，执行 *p=9，结果？',['b 变为 9','p 指向地址 9','a 自动变为 9','没有变化'],0,'*p 选择当前目标位置 b，右边 9 写入该位置。'],
 ['执行 *p=9 前最先确定什么？',['p 当前指向哪个有效目标','变量名长短','机器外壳颜色','注释行数'],0,'相同写法可以改不同目标，必须沿前面语句追踪 p 当前保存的地址。']
]);

B('c-array-start','09 · 数组：连续保存多个同类数据','读懂 int a[3]，从 a[0] 开始逐个访问，再理解数组与指针的联系。',[
 S('为什么需要数组？',['要保存三个整数，可以分别写三个变量，也可以使用一个数组把三个同类型元素放在一起。','int a[3]={10,20,30} 表示 a 有 3 个 int 元素。它们的编号叫“下标”，从 0 开始，所以有效下标为 0、1、2。'],{code:'int a[3] = {10, 20, 30};',table:{heads:['写法','对应元素的值'],rows:[['a[0]','10'],['a[1]','20'],['a[2]','30']]}}),
 S('访问元素时，[] 里面是下标',['a[1]=7 修改的是第二个元素。a[3] 不是第三个元素，而是数组边界之后；这里没有这个元素，不能读写。','int a[3] 中的 3 表示元素数量；使用时 a[2] 中的 2 表示下标。这两个阶段里的数字用途不同。'],{code:'a[1] = 7;  // 数组变为 {10, 7, 30}'}),
 S('从元素地址开始联系指针',['&a[0] 取得首元素的地址，可以写 int *p=&a[0]。此时 *p 访问的就是 a[0]。','常见表达式中数组名 a 可以转换为首元素地址，所以 int *p=a 也常用。但是数组本身仍是三个元素，p 只是一个保存地址的变量。不要因为这行代码就认为数组和指针大小相同。'],{code:'int *p = &a[0];\n*p = 5;  // 修改 a[0]',note:'假设 int 为 4 字节，相邻元素地址相隔 4 字节。后面的指针算术课程再学习 p+1 如何到下一元素。'})
],['int a[3] 建立 3 个 int 元素，有效下标为 0、1、2。','[] 访问一个元素，&a[0] 取得首元素地址，*p 可沿这个地址访问元素。','数组元素连续存放；完整数组所需总空间与一个指针自身空间要分开计算。'],{prompt:'int a[3]={10,20,30}; int *p=&a[0]; *p=5; a[1]=7; 最终数组各元素是什么？',answer:'p 指向 a[0]，所以 *p=5 将第一项改成 5。a[1]=7 直接改第二项。第三项未修改仍为 30，结果为 {5,7,30}。'},'下标从 0 开始，含 3 个元素不意味着可用 a[3]；数组有效范围必须先检查。',[
 ['int a[3]={10,20,30}; a[1] 是？',['10','20','30','3'],1,'下标 0 是第一项 10，下标 1 是第二项 20。'],
 ['上述数组可访问的下标范围？',['0～2','1～3','0～3','任意非负数'],0,'3 个元素从 0 数起，最后为数量减 1，即 2。'],
 ['int *p=&a[0]; *p=7 修改？',['a[0]','a[1]','所有元素','只修改 p 的地址'],0,'&a[0] 是第一项地址，p 指向它，*p 的写入目标就是第一项。']
]);

B('c-function-start','10 · 函数：传一个值与传一个地址','函数可以接收数据、执行几条语句并返回结果；传整数和传地址的效果不同。',[
 S('把一段工作起个名字',['函数可以理解为有名字的一段操作，调用它时执行这段代码。int add_one(int n) 表示函数叫 add_one，接收一个 int，返回一个 int。','调用 add_one(3) 时，把 3 交给函数里的 n。return n+1 算出 4 并交回调用处。'],{code:'int add_one(int n) {\n    return n + 1;\n}\n// 调用：int y = add_one(3); 结果 y 为 4',tokens:[['前面的 int','函数返回结果的类型。'],['add_one','函数名。'],['int n','形参：函数内部接收本次输入的变量。'],['return n + 1;','算出结果并结束本次函数调用。'],['{ }','包住函数体中的操作。']]}),
 S('传整数得到一个值副本',['调用 set_value(x) 时，形参 n 得到 x 当前值的副本。给 n 赋 7，不会直接改外面的 x。','要使用返回结果，可以写 x=add_one(x)，明确把结果写回 x。不要以为函数内部改了 n，外面同名或相关变量就都改变。'],{code:'void set_value(int n) {\n    n = 7;\n}\n// int x=10; set_value(x); 后 x 仍为 10',note:'void 在返回类型位置表示这个函数不返回一个值。'}),
 S('传地址才可以沿地址改原变量',['set_target(&x) 把 x 的地址交给形参 p。p 是地址副本，但它指向外面同一个 x，所以 *p=7 会改 x。','函数调用里的 &x 是取得地址；函数参数里的 int *p 是声明指针；函数体里的 *p=7 是访问目标。把三处串起来读，就不必背“传引用”这种模糊说法。'],{code:'void set_target(int *p) {\n    *p = 7;\n}\n// int x=10; set_target(&x); 后 x 为 7',read:[['set_target(&x)','取 x 的地址，作为本次调用的输入。'],['int *p','函数用指针形参 p 接收该地址。'],['*p=7;','沿地址访问外面的 x，将其改为 7。']]})
],['函数有名字、输入和操作，return 可把一个结果交回调用者。','C 的普通参数按值传递，函数内改整数形参不自动改调用者变量。','传 &x 后，函数的指针形参可以通过 *p 访问原 x，但指针形参自身仍是副本。'],{prompt:'int x=10; set_value(x); set_target(&x); 按本课两个函数，先后 x 是多少？',answer:'set_value(x) 内 n 得到 10 的副本，只把 n 改为 7，所以 x 仍为 10。set_target(&x) 中 p 指向 x，*p=7 写入原变量，所以最终 x=7。'},'传地址不代表地址一定有效。调用者要确保函数使用期间目标存在，函数也应按接口需要检查空指针。',[
 ['add_one(3) 执行 return n+1，返回？',['3','4','1','地址'],1,'本次形参 n=3，表达式 n+1=4，由 return 交回。'],
 ['void f(int n){n=7;}，x=10 后 f(x)，x？',['10','7','17','空指针'],0,'n 是 x 值的副本，给 n 赋值不写到外面 x。'],
 ['void g(int *p){*p=7;}，g(&x) 后 x？',['7','始终 10','sizeof(int)','函数名'],0,'形参 p 保存 x 的地址，*p=7 沿地址写 x。']
]);

B('c-struct-start','11 · 结构体：把相关数据放在一起','先学会 struct、成员访问 . 和指针访问 ->，再学习填充与对齐。',[
 S('为什么不是一个数组？',['温度值与传感器编号属于同一份记录，但它们可以有不同类型、不同用途。结构体把这些字段组合成一种类型。','数组强调多个同类型元素；结构体强调一份记录里有几个具名字段，这些字段叫“成员”。'],{code:'struct Sensor {\n    int id;\n    int temperature;\n};',tokens:[['struct','声明一种结构体类型。'],['Sensor','这里的结构体类型名称。'],['id、temperature','成员名，每份 Sensor 记录都有自己的这两个字段。'],['结尾的 ;','结束结构体类型定义。']]}),
 S('创建变量，用点号访问成员',['上面的代码先定义类型；struct Sensor s; 才创建一份具体记录 s。','s.id=1 给这份记录的编号赋值；s.temperature=25 设置温度。点号左边是结构体变量，右边是成员名。'],{code:'struct Sensor s;\ns.id = 1;\ns.temperature = 25;'}),
 S('指针访问成员为何写 ->？',['struct Sensor *p=&s 让 p 指向这份记录。(*p).temperature 先沿地址得到 s，再用点号访问成员。','p->temperature 是同一操作的常用简写，箭头不是减号加“大于”比较。p->temperature=30 会修改 s.temperature。'],{code:'struct Sensor *p = &s;\np->temperature = 30;\n// 等价于 (*p).temperature = 30;',table:{heads:['写法','使用什么访问','含义'],rows:[['s.temperature','结构体变量 s','访问 s 的温度。'],['p->temperature','指向结构体的指针 p','沿 p 找记录，再访问温度。'],['(*p).temperature','先访问目标再取成员','与 p->temperature 等价。']]}})
],['struct 定义结构体类型，把一组具名成员组合成一份记录。','结构体变量用点号访问成员，结构体指针用 -> 访问目标成员。','先理解成员的用途和访问，再计算结构体占用；成员大小简单相加可能漏掉填充。'],{prompt:'s.temperature=25; p=&s; p->temperature=30; 最后 s.temperature 为多少？',answer:'p 保存 s 的地址。p->temperature 等价于 (*p).temperature，写入的是 s 的温度成员，因此最后为 30。不会创建另一份结构体副本。'},'struct Sensor 是类型，s 是该类型的变量，p 是指向该类型变量的指针，三者不要混成一个东西。',[
 ['结构体变量 s 访问 id 应写？',['s.id','s->id（s 非指针）','sizeof.id','&.id'],0,'s 是具体结构体变量，用点号加成员名。箭头适用于指向结构体的指针。'],
 ['p 指向 s，p->id 等价于？',['(*p).id','*p.id','p.id','&p.id'],0,'先对 p 解引用得到目标记录，再访问 id，括号让这一顺序明确。'],
 ['定义 struct Sensor {...}; 后，是否已经创建变量 s？',['没有，还需声明 s','已经自动创建','自动创建 3 个 s','p 一定存在'],0,'这是类型定义，只有再写 struct Sensor s 等声明才创建具体变量。']
]);

B('c-start-variable','01 · 变量：给一份数据起名字','读懂 int x = 10;，分清变量的名字、类型和当前值。',[
 S('先看一行代码',['变量可以先理解为“有名字、用来保存数据的位置”。例如记录年龄、温度、计数次数，都需要保存当前数据。','下面创建一个名字为 x 的整数变量，并给它初值 10。之后写 x，就能使用这份数据；写 x=20，就能更新它。'],{code:'int x = 10;',tokens:[['int','类型名，说明 x 用来保存整数，例如 0、10、-3。'],['x','变量名，由你起名；这里叫 x，也可以叫 count。'],['= 10','在创建变量时，把初始值设为 10。'],[';','表示这条声明结束，不是数据的一部分。']]}),
 S('值可以变，名字不必变',['代码通常从上往下执行。执行完第一行，x 是 10；执行完第二行，x 是 20。第二行没有重新创建变量，而是修改已有变量。','x=20 中的等号是“把右边结果存进左边”，不是数学里的“判断两边是否相等”。判断相等通常写 ==。'],{code:'int x = 10;\nx = 20;',read:[['int x = 10;','创建 x，初值为 10。'],['x = 20;','把 x 当前保存的 10 替换为 20。']]}),
 S('类型有什么用？',['int 适合保存整数。char 常用来保存一个字符，例如字符 \'A\'。类型会影响能保存的数据范围、占用空间和运算规则。','你现在只需先分清三件事：名字是 x，类型是 int，当前值是 20。它们回答不同问题。'],{table:{heads:['想知道什么','本例回答'],rows:[['变量叫什么？','x'],['用什么类型保存？','int'],['当前保存多少？','20']]}})
],['变量名用于找到并使用一份数据；int 是类型，x 是名字，10 是初值。','创建后可以通过赋值更新变量：x=20 的右边是新值，左边是要修改的位置。','变量的值与占用字节数分开看；值从 10 改到 20，普通 int 的大小不会因此改变。'],{prompt:'int count=3; count=8; 两行执行后 count 是多少？哪一行创建变量？',answer:'第一行 int count=3 创建变量 count，初值为 3。第二行 count=8 修改已有变量。最后 count 为 8。名字仍是 count，类型仍是 int。'},'本课用的是普通局部变量，使用前给它初值。不要读取没有初始化的局部整数。',[
 ['int count=6; 中变量名是什么？',['int','count','6',';'],1,'int 指明类型，count 是这份数据的名字，6 是初值，分号结束声明。'],
 ['int x=2; x=9; 执行后 x 的值？',['2','9','11','无法更新'],1,'先创建值为 2 的 x，再把右边 9 存进同一个 x，旧值被替换。'],
 ['x=7 中的 = 主要表示？',['把右边结果存入左边','判断 x 是否等于 7','取地址','求字节数'],0,'在这里是赋值。判断相等写 x==7；取地址和求大小分别用 & 与 sizeof。']
]);

B('c-start-bytes','02 · 内存、bit 和 byte','弄清“占 4 字节”在说什么，而不是把 4 字节当成数值 4。',[
 S('数据需要存放位置',['程序运行时，数据需要保存在计算机可访问的存储中。先把内存想成一排有编号的小格子：格子可以存放数据，编号帮助我们找到它。','这个比喻用于理解位置与内容。实际编译器也可能把局部变量放寄存器；后面学调试时再讨论具体存放方式。']),
 S('bit 是位，byte 是字节',['bit 叫“位”，一位可以表示 0 或 1。多个位组合才能表示更多数值。','常见 STM32 环境中 1 byte（字节）=8 bit（位），所以 4 字节=32 位。C 标准中的一个字节含几位由 CHAR_BIT 表示；本入门示例均采用 8 位字节。'],{table:{heads:['说法','常见 8 位字节环境的换算'],rows:[['1 字节','8 位'],['2 字节','16 位'],['4 字节','32 位'],['8 字节','64 位']]}}),
 S('空间大小与数据内容分开',['假设本例 int 占 4 字节，int x=10 就是用一个 4 字节的整数位置保存数值 10。这里的 4 是空间大小，10 是数据内容。','将 x 改为 100，仍是同一个 int，通常仍占 4 字节。不要把十进制数字写了几位，误当成变量用了几个字节。'],{code:'int x = 10;   // 本例假设 int 占 4 字节\nx = 100;      // 值改变，int 类型的大小不变',note:'暂时不需要把 10 拆成每个字节的二进制。先分清“放多少”与“用多大位置放”。'})
],['bit 是二进制位；本例 byte 是 8 位，因此 4 字节是 32 位。','“int 占 4 字节”描述保存该类型所需的空间，不是说它只能保存数值 4。','类型决定普通变量所需空间，变量当前值改变不会把它变成更大或更小的类型。'],{prompt:'在 int 为 4 字节、每字节 8 位的环境，int x=1; 改成 x=999 后，大小和位数怎样变化？',answer:'x 的值从 1 变为 999，但类型仍是 int，所以仍为 4 字节，也就是 4×8=32 位。数值 999 的十进制位数为 3，不代表占 3 字节。'},'32 位 MCU 并不意味着所有类型都占 32 位。char、int、指针要分别查看。',[
 ['常见 STM32 的 4 字节包含多少位？',['4','8','16','32'],3,'采用每字节 8 位的前提，4×8=32 位。字节和位是两种单位。'],
 ['假设 int 为 4 字节，x 从 1 改成 100，x 所占空间通常？',['仍为 4','变成 100','变成 3','变成 1'],0,'普通 int 的大小由类型决定，不按当前十进制数字的长度变化。'],
 ['“变量的值是 10”与“变量占 4 字节”是否同一概念？',['不是，前者是内容，后者是空间','是','只能有一个说法','由变量名字决定'],0,'一份数据有内容，也需要一定空间，两者可以同时描述同一变量。']
]);

B('c-start-expression','03 · 先读懂代码里的符号','认识 =、==、括号、分号和注释，再看它们在一小段代码中怎样工作。',[
 S('一条语句在做什么？',['先问这行是创建变量、计算新值，还是检查条件。相同字符出现在不同位置，含义可能不同，不能只按符号形状猜。','例子中的 x+2 先计算，随后把结果存入 y；x 原来的内容不会被自动修改。'],{code:'int x = 3;\nint y = x + 2;  // y 为 5，x 仍为 3',read:[['int x=3;','创建整数 x，初值 3。'],['int y=x+2;','取 x 的值 3，计算 3+2，把 5 作为 y 的初值。'],['// 后面的文字','注释给人阅读，不执行里面的说明。']]}),
 S('赋值与比较要分开',['x=5 表示修改 x。x==5 表示检查 x 当前是否等于 5，得到一个判断结果。','比较结果在 C 中通常用整数 0 表示假、1 表示真。比较本身不把 x 改成 5。'],{table:{heads:['符号/写法','这里的含义'],rows:[['=','赋值或初始化：把右边结果存入左边。'],['==','判断是否相等。'],['( )','可以分组表达式、包住类型，或写函数参数；要看上下文。'],[';','结束这里的一条语句/声明。'],['//','从这里到行尾是注释。']]}}),
 S('先按顺序算，不要一眼猜结果',['下面第二行先取旧 x=3，计算 x+1=4，再写回 x。赋值不是让左边和右边同时变化。','读代码时可在纸上记每行执行后的 x 值；指针课程也会沿用这种方法。'],{code:'int x = 3;\nx = x + 1;  // 执行后 x 为 4'})
],['读代码先识别类型、名字、计算表达式和结束分号。','= 是存值，== 是比较；比较不自动修改变量。','赋值右边先算出结果，再写回左边的位置，注释只用于说明。'],{prompt:'int x=3; int y=x+2; x=x+1; 最终 x 和 y 各是多少？',answer:'第一行 x=3。第二行用当时的 x 计算出 y=5；y 是独立变量，不会一直随 x 联动。第三行将 x 改为 4，因此最终 x=4、y=5。'},'括号并不意味着里面一定是函数参数。例如 sizeof(int) 的括号中是类型。',[
 ['int x=3; int y=x+2; 中 y 的初值？',['2','3','5','6'],2,'先取 x 的 3，与 2 相加得到 5，再初始化 y。'],
 ['检查 x 是否等于 5，应写？',['x=5','x==5','&x','sizeof x'],1,'== 比较当前值；= 会修改 x，不能混用。'],
 ['x=3; x=x+1; 后 x？',['1','3','4','x 永不改变'],2,'右边用旧值 3，计算 4，然后写回左边 x。']
]);

B('c-sizeof','04 · sizeof：询问占多少字节','sizeof 是 C 的运算符，用来取得一种类型或一个对象的存储大小。',[
 S('sizeof 问的是空间，不是内容',['sizeof 可以读作“size of”，即“……的大小”。例如 sizeof(int) 问一个 int 类型的对象需要多少个 C 字节。它不在问 int 的数值是多少。','假设我们的示例环境中 int 为 4 字节，int x=10; 后 sizeof(x) 为 4，而 x 为 10。这是对同一个变量提出的两个问题。'],{code:'int x = 10;\n// x 的值：10\n// sizeof(x) 的结果：4（本例 int 为 4 字节）',tokens:[['sizeof','求存储大小的运算符；不是普通函数。'],['sizeof(int)','询问 int 类型所需字节数；类型名必须加括号。'],['sizeof(x)','根据变量 x 的类型求大小。'],['sizeof x','对变量时也可这样写；初学时可统一用 sizeof(x)。']]}),
 S('一步步计算数组大小',['int a[3] 是三个 int 排在一起。在定义 a 的这个作用域里，sizeof(a) 是整个数组的大小，不是只看第一个元素。','若一个 int 为 4 字节，三个就是 3×4=12。sizeof(a[0]) 是单个元素大小 4。总大小除以单个大小，12/4=3，就是元素个数。'],{code:'int a[3] = {10, 20, 30};\n// sizeof(a)    → 12\n// sizeof(a[0]) → 4\n// sizeof(a) / sizeof(a[0]) → 3',note:'这里 a 是当前作用域里的真实数组。传入函数后有额外规则，先学完“数组入门”再看原数组专题。'}),
 S('哪些事情 sizeof 不会做？',['普通 int 的大小取决于类型，不取决于当前保存的是 10 还是 999。它不会把变量内容改掉。','普通非变长数组表达式作为 sizeof 操作数时不执行。例如 sizeof(x++) 只依据 x++ 的类型求大小，普通 int x 不会因此自增。C 的变长数组有例外，先把这个边界记住。','sizeof 的结果类型叫 size_t，是表示大小的无符号整数类型。打印它用 %zu；不用现在就学习完整的整数转换规则。'],{code:'#include <stdio.h>\nint main(void) {\n    int x = 10;\n    printf("x=%d, sizeof(x)=%zu\\n", x, sizeof(x));\n    return 0;\n}',table:{heads:['常见写法','在问什么'],rows:[['sizeof(char)','一个 char 所需字节数，C 保证结果为 1。'],['sizeof(int)','一个 int 所需字节数，实际值要看环境。'],['sizeof(x)','按 x 的类型求大小。'],['sizeof(a)','a 是本地完整数组时，求全部元素总大小。']]}})
],['sizeof 返回存储大小，单位是 C 字节；sizeof(char) 恒为 1，int 大小由环境确定。','sizeof(int) 对类型求大小，sizeof(x) 对变量的类型求大小，和 x 当前内容是两件事。','对当前作用域完整数组，sizeof(a)=元素个数×单个大小；函数形参数组不能直接套用该长度公式。'],{prompt:'假设 int 为 4 字节：int x=100; int a[2]={7,8}; sizeof(x)、sizeof(a)、sizeof(a[0]) 各是多少？',answer:'x 是一个 int，大小为 4，不是数值 100。a 是两个 int 的数组，总大小 2×4=8。a[0] 是一个 int，大小为 4。三个结果分别为 4、8、4。'},'sizeof 返回的是字节数，不是元素个数，不是字符串可见字符数。sizeof 是运算符；普通表达式不求值，变长数组相关情况需另外学习。',[
 ['假设 int 占 4 字节：int x=50; sizeof(x) 是？',['50','4','1','sizeof 会修改 x'],1,'看 x 的类型 int，每个 int 为 4 字节，所以结果 4；50 是它的内容，不参与普通类型大小计算。'],
 ['假设 int 占 4 字节：int a[3]; sizeof(a) 是？',['3','4','12','10'],2,'在完整数组的定义作用域，三个 int 的总大小为 3×4=12。'],
 ['对普通 int x，sizeof(x++) 会让 x 自增吗？',['不会','会加 1','会加 4','总无法编译'],0,'该操作数不属于变长数组情况，sizeof 依据表达式类型求大小，不执行 x++。这不是说任意带变长数组的 sizeof 都不求值。']
]);

B('c-address','05 · &：取得变量的地址','分清 x 的内容与 &x 的位置：&x 的 & 是取地址运算符。',[
 S('地址就是“到哪里找”',['继续用编号格子的比喻：一个变量保存内容，同时位于某个位置。访问内容与询问位置是两件事。','假设 x 从地址 0x1000 开始保存，值为 10，那么 x 取得 10，&x 取得地址 0x1000。这个地址是示意，不是运行时必须出现的固定数。'],{code:'int x = 10;\n// x  → 当前内容 10\n// &x → x 所在的地址（例如 0x1000）',table:{heads:['表达式','它取得什么'],rows:[['x','x 当前保存的整数。'],['&x','x 的地址。']]}}),
 S('0x1000 是什么？',['0x 表示后面的数字按十六进制书写。你现在可以把 0x1000 当作一个位置标签，不需要先背完进制转换。','地址的实际表示和数值依平台及运行情况不同。在真实代码中应写 &x 获取地址，不能直接把教学地址写进指针去访问。']),
 S('同一个 &，位置不同意思也不同',['&x 只有一个操作数 x，这里是取地址。a & b 左右有两个操作数，这里是按位与，用于二进制位计算。','a && b 是两个连续的 &，表示逻辑与，常用于判断两个条件都成立。本课的 &x 与这两种写法要分开。'],{table:{heads:['写法','含义','简单读法'],rows:[['&x','取地址','取得 x 的位置。'],['a & b','按位与','逐位计算，后面位运算课详细讲。'],['a && b','逻辑与','两个条件都为真时，结果为真。']]}})
],['x 通常用于取得变量保存的值，&x 用于取得该变量的地址。','地址示意如 0x1000，只帮助理解位置，实际使用应由 &x 等合法方式获得。','&x、a&b、a&&b 在 C 中分别是取地址、按位与、逻辑与，不能当成同一个操作。'],{prompt:'int x=10; 若 x 的示意地址为 0x1000，执行 x=20 后，x 与 &x 分别表示什么？',answer:'x 的内容变为 20。对同一个仍存活的 x，&x 仍取得它的位置，示意中仍为 0x1000。修改里面的值，不会让这个已有变量因为赋值就换到另一位置。'},'不要把内存地址当作变量的整数值。后面的指针要保存地址，而不是随便把整数 10 当地址。',[
 ['int x=10; &x 取得的是？',['x 的地址','整数 10','x 的字节数','x 加 1'],0,'& 写在变量前且作为单目运算符时取得其地址，不读取为业务整数 10。'],
 ['本课中 &x 与 a&b 是否相同含义？',['不同，分别取地址与按位与','相同','两者都是乘法','两者都求大小'],0,'&x 只有一个操作数，a&b 有两个。根据使用位置识别含义。'],
 ['示意地址为 0x1000，真实程序访问 x 最应怎样获得地址？',['用 &x','直接假定所有 x 都在 0x1000','用 sizeof(x)','用 x+1000'],0,'&x 由程序取得实际地址，教学示意数字不应硬编码为真实目标地址。']
]);

// 保持第一轮练习只检查刚学的概念，进阶求值规则另行展开。
const sizeLesson=beginnerLessons.find(l=>l.id==='c-sizeof');
sizeLesson.basics.sections[2].optional=true;
sizeLesson.quiz[2]={id:'c-sizeof-q3',prompt:'sizeof(char) 的结果表示一个 char 占多少个 C 字节？',options:['1','8','与字符值相同','由字符名字长度决定'],answer:0,explain:'C 把 char 定义为一个字节大小，所以 sizeof(char) 为1。这里数的是字节，至于一个字节有几位由 CHAR_BIT 表示；常见 STM32 为8位。'};
